function cmpSeq(a,b){for(let i=0;i<Math.min(a.length,b.length);i++)for(let j=0;j<4;j++){if(a[i][j]!==b[i][j])return a[i][j]<b[i][j]?-1:1}return a.length-b.length}
export function book(a){const n=a.meetings.length,byid=new Map(a.meetings.map((m,i)=>[m.id,i])),lo=Date.parse(a.range_start),hi=Date.parse(a.range_end),blocks=a.blocks.map(b=>({r:b.room_id,s:Date.parse(b.start),e:Date.parse(b.end)})),opts=a.meetings.map(m=>candidates(m).flatMap(s=>m.eligible_rooms.map(r=>({id:m.id,room:r,s,e:s+m.minutes*60000,value:m.value,people:m.people,idx:byid.get(m.id)}))).filter(x=>x.s>=lo&&x.e<=hi&&!blocks.some(b=>b.r===x.room&&x.s<b.e&&b.s<x.e)));const chosen=Array(n).fill(null);let best=null;
function ok(x){for(const y of chosen){if(!y)continue;if(x.room===y.room&&x.s<y.e&&y.s<x.e)return false;for(const p of x.people)if(y.people.includes(p)){const prev=x.s>=y.s?y:x,next=prev===x?y:x;if(next.s<prev.e+a.transitions[prev.room][next.room]*60000)return false}}return true}
function evaluate(v,c){for(let i=0;i<n;i++)if(chosen[i])for(const req of a.meetings[i].requires){const j=byid.get(req);if(!chosen[j]||chosen[j].e>chosen[i].s)return}const arr=chosen.filter(Boolean).map(x=>({meeting_id:x.id,room_id:x.room,start:iso(x.s),end:iso(x.e)})).sort((x,y)=>x.meeting_id<y.meeting_id?-1:x.meeting_id>y.meeting_id?1:0),seq=arr.map(x=>[x.meeting_id,x.room_id,x.start,x.end]);if(!best||v>best.v||v===best.v&&(c>best.c||c===best.c&&cmpSeq(seq,best.seq)<0))best={v,c,arr,seq}}
function dfs(i,v,c){if(i===n){evaluate(v,c);return}chosen[i]=null;dfs(i+1,v,c);for(const x of opts[i])if(ok(x)){chosen[i]=x;dfs(i+1,v+x.value,c+1)}chosen[i]=null}dfs(0,0,0);return {value:best?.v??0,count:best?.c??0,bookings:best?.arr??[]}}
